// Textures of the card background: stars for the glitter, noise for the
// brushed metal, and the QR icon on the chip. Everything is drawn in place —
// no images from the server.

import {DESIGN} from '@components/wallet/visual/card/layout';
import {Vec2} from '@components/wallet/visual/math';

/**
 * Stars from the design (Figma «Stars»): four-pointed, 8×8. The green channel
 * holds the twinkle phase, the alpha — the star itself.
 */
const STARS: Vec2[] = [[70, 42], [272, 148], [25, 22], [210, 178], [104, 56], [203, 133], [220, 155], [52, 21], [120, 36], [51, 67]];
const PHASES = [0.05, 0.63, 0.22, 0.87, 0.42, 0.12, 0.74, 0.33, 0.55, 0.94];

export function starsCanvas(scale = 3): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = Math.round(DESIGN.width * scale);
  c.height = Math.round(DESIGN.height * scale);
  const g = c.getContext('2d');
  g.scale(scale, scale);
  STARS.forEach(([x, y], i) => {
    // The same outline as in the design: points at 4, notches at 0.8485 on the diagonal.
    const k = 0.8485;
    g.beginPath();
    g.moveTo(x, y - 4);
    g.lineTo(x + k, y - k);
    g.lineTo(x + 4, y);
    g.lineTo(x + k, y + k);
    g.lineTo(x, y + 4);
    g.lineTo(x - k, y + k);
    g.lineTo(x - 4, y);
    g.lineTo(x - k, y - k);
    g.closePath();
    g.fillStyle = `rgb(255, ${Math.round(PHASES[i] * 255)}, 0)`;
    g.fill();
  });
  return c;
}

export interface NoiseData {
  data: Uint8Array,
  size: number
}

/** 256×256 noise: blurred along the row (brushing) plus fine grain. */
export function noiseData(): NoiseData {
  const n = 256;
  let seed = 0x2545f491;
  const random = () => {
    seed ^= seed << 13;
    seed >>>= 0;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    seed >>>= 0;
    return (seed & 0xffff) / 0xffff;
  };
  const base = new Float32Array(n * n);
  for(let i = 0; i < base.length; i++) base[i] = random();
  const out = new Uint8Array(n * n);
  const r = 9;
  for(let y = 0; y < n; y++) for(let x = 0; x < n; x++) {
    let acc = 0;
    for(let o = -r; o <= r; o++) acc += base[y * n + ((x + o + n) % n)];
    let v = acc / (2 * r + 1);
    v = 0.5 + (v - 0.5) * 3.4;
    const combined = 0.68 * v + 0.32 * random();
    out[y * n + x] = Math.max(0, Math.min(255, combined * 255));
  }
  return {data: out, size: n};
}

